void Check(bool value,string message="Assertion failed"){if(!value)throw new Exception(message);}
async Task Reject(Func<Task> action,int? expected=null){try{await action();throw new Exception("Expected rejection");}catch(AccountsException e){if(expected.HasValue)Check(e.Status==expected);}catch(ArgumentException)when(!expected.HasValue){}catch(FarmStay.Application.Interfaces.Common.TenantAccessException e){if(expected.HasValue)Check(e.Status==expected);}}
