async Task<T> Run<T>(bool asCustomer,Func<IServiceProvider,Task<T>> task){var m=asCustomer?member:staff;accessor.HttpContext=new DefaultHttpContext();accessor.HttpContext.User=new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.NameIdentifier,m.UserId.ToString()),new Claim("UserMembershipId",m.UserMembershipId.ToString()),new Claim("FarmHouseId",m.FarmHouseId.ToString()),new Claim(ClaimTypes.Role,asCustomer?"Customer":"Admin")},"fixture"));accessor.HttpContext.Request.Headers["FarmHouseId"]=m.FarmHouseId.ToString();await using var scope=provider.CreateAsyncScope();return await task(scope.ServiceProvider);}
async Task<Booking> Book(string reference,string status,decimal total,decimal advance){var booking=new Booking{FarmHouseId=fa.FarmHouseId,CustomerUserId=customer.UserId,BookingReference=reference,FullName=customer.FullName,MobileNumber=customer.MobileNumber,AdultCount=1,PersonCount=1,CheckInDate=DateTime.Today,CheckOutDate=DateTime.Today.AddDays(1),StayDays=1,TotalAmount=total,BaseAmount=total,AdvanceAmount=advance,CurrencyCode="INR",Status=status,ActualCheckOutAt=status=="CheckedOut"?DateTime.Now:null,CreatedBy=admin.UserId};db.Add(booking);await db.SaveChangesAsync();return booking;}
async Task<PaymentTransaction> Paid(Booking booking,string type,decimal amount,string method="Cash"){var payment=new PaymentTransaction{FarmHouseId=fa.FarmHouseId,BookingId=booking.BookingId,PaymentType=type,PaymentMethod=method,Amount=amount,CurrencyCode="INR",PaymentStatus="Success",PaidAt=DateTime.Now,VerifiedAt=DateTime.Now,IdempotencyKey="finance-fixture:"+Guid.NewGuid().ToString("N"),CreatedBy=admin.UserId};db.Add(payment);await db.SaveChangesAsync();return payment;}
